package vmcompat.tests;
import vmcompat.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import org.lwjgl.*;
import org.lwjgl.glfw.*;
import org.lwjgl.opengl.*;
import static vmcompat.Counters.Key.*;
/** Extends the existing GL fixtures: real pixels and actual source mutations, not a replay renderer. */
public final class ResourceMutationTests {
    static void check(boolean yes,String text){if(!yes)throw new AssertionError(text+" GL="+Integer.toHexString(GL11.glGetError()));}
    static long n(Counters.Key k){return Counters.snapshot()[k.ordinal()];}
    static int buffer(int... words){int b=Buffers.glGenBuffers();GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,b);IntBuffer data=BufferUtils.createIntBuffer(words.length).put(words).flip();Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,data,GL15.GL_DYNAMIC_DRAW);return b;}
    static void write(int buffer,int offset,int value){GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,buffer);Buffers.glBufferSubData(GL15.GL_ARRAY_BUFFER,offset,BufferUtils.createIntBuffer(1).put(0,value));}
    static int program(String type){int p=Shaders.glCreateProgram();int v=Shaders.compileRaw(GL20.GL_VERTEX_SHADER,"#version 410 core\nvoid main(){vec2 q=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(q*2-1,0,1);}");int f=Shaders.compileRaw(GL20.GL_FRAGMENT_SHADER,"#version 410 core\nuniform "+type+"samplerBuffer pixels;out vec4 color;void main(){color=vec4(float(texelFetch(pixels,0).x)/255.,0,0,1);}");Shaders.glAttachShader(p,v);Shaders.glAttachShader(p,f);Shaders.glLinkProgram(p);check(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=0,"program");GL20.glDeleteShader(v);GL20.glDeleteShader(f);return p;}
    static int range(int source,int offset,int size){int tex=Textures.glCreateTextures(GL31.GL_TEXTURE_BUFFER);Samplers.glActiveTexture(GL13.GL_TEXTURE0+80);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,tex);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32I,source,offset,size);return tex;}
    static void draw(int p,int texture,int expected){Shaders.glUseProgram(p);Samplers.glActiveTexture(GL13.GL_TEXTURE0+80);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,texture);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"pixels"),80);Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);ByteBuffer pixel=BufferUtils.createByteBuffer(4);GL11.glReadPixels(16,16,1,1,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,pixel);check((pixel.get(0)&255)==expected,"pixel expected "+expected+", got "+(pixel.get(0)&255));check(GL11.glGetError()==0,"draw error");}
    public static void main(String[] args)throws Exception{
        GLFWErrorCallback cb=GLFWErrorCallback.createPrint(System.err);cb.set();check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,GLFW.GLFW_FALSE);
        long window=Context.createWindow(32,32,"Range mutation fixture",0,0);Context.makeCurrent(window);GLCapabilities caps=Context.capabilities();GL11.glViewport(0,0,32,32);
        int p=program("i"),source=buffer(1,2,3,4,5,6,7,8),a=range(source,4,4),b=range(source,8,4);
        try{
            long cpuBefore=n(RANGE_CPU_UPDATES);write(source,4,2);draw(p,a,2);draw(p,b,3);if(Counters.ENABLED&&Options.RANGE_CPU&&Options.MIRROR)check(n(RANGE_CPU_UPDATES)>cpuBefore,"known CPU range upload used");long copies=n(RANGE_COPIES_ALL);draw(p,a,2);draw(p,b,3);if(Options.RANGES)check(n(RANGE_COPIES_ALL)==copies,"unchanged ranges skipped");
            write(source,4,9);draw(p,a,9);draw(p,b,3);copies=n(RANGE_COPIES_ALL);write(source,28,99);draw(p,a,9);if(Options.RANGES)check(n(RANGE_COPIES_ALL)==copies,"nonoverlap skip");
            write(source,4,10);draw(p,a,10);write(source,4,11);draw(p,a,11);
            int input=buffer(12);Gl41.glCopyNamedBufferSubData(input,source,0,4,4);draw(p,a,12);
            GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,source);ByteBuffer mapped=Buffers.glMapBufferRange(GL15.GL_ARRAY_BUFFER,4,4,GL30.GL_MAP_WRITE_BIT);mapped.order(ByteOrder.nativeOrder()).putInt(0,13);check(Buffers.glUnmapBuffer(GL15.GL_ARRAY_BUFFER),"unmap");draw(p,a,13);
            GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,source);mapped=Buffers.glMapBufferRange(GL15.GL_ARRAY_BUFFER,4,4,GL30.GL_MAP_WRITE_BIT|GL30.GL_MAP_FLUSH_EXPLICIT_BIT);mapped.order(ByteOrder.nativeOrder()).putInt(0,14);Buffers.glFlushMappedBufferRange(GL15.GL_ARRAY_BUFFER,0,4);check(Buffers.glUnmapBuffer(GL15.GL_ARRAY_BUFFER),"explicit unmap");draw(p,a,14);
            Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,a);int savedRead=GL11.glGetInteger(GL31.GL_COPY_READ_BUFFER),savedWrite=GL11.glGetInteger(GL31.GL_COPY_WRITE_BUFFER),savedActive=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);long alloc=n(RANGE_ALLOCATIONS);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32I,source,4,4);if(Options.RANGE_STORAGE)check(n(RANGE_ALLOCATIONS)==alloc,"same size storage reused");check(GL11.glGetInteger(GL31.GL_COPY_READ_BUFFER)==savedRead&&GL11.glGetInteger(GL31.GL_COPY_WRITE_BUFFER)==savedWrite&&GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE)==savedActive,"range update restores physical buffer/active texture bindings");
            GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,source);Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,BufferUtils.createIntBuffer(8).put(new int[]{21,22,23,24,25,26,27,28}).flip(),GL15.GL_DYNAMIC_DRAW);draw(p,a,22);draw(p,b,23);
            write(source,4,29);for(int i=0;i<140;i++)write(source,28,i);draw(p,a,29);
            Buffers.unknownWrite(source);copies=n(RANGE_COPIES_ALL);draw(p,a,29);draw(p,a,29);if(Counters.ENABLED)check(n(RANGE_COPIES_ALL)>copies,"unknown producer stays conservative");
            write(source,4,30);Buffers.glDeleteBuffers(source);draw(p,a,30); // Deleted source's live texture view keeps the last contents.
            source=Buffers.glGenBuffers();GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,source);Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,BufferUtils.createIntBuffer(8).put(new int[]{41,42,43,44,45,46,47,48}).flip(),GL15.GL_DYNAMIC_DRAW);draw(p,a,30);
            Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,a);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32I,source,0,4);draw(p,a,41);
            Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,a);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32UI,source,0,4);int up=program("u");draw(up,a,41);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,a);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32I,source,4,8);draw(p,a,42);Shaders.glDeleteProgram(up);
            // Storage shrink is followed by rebinding a valid range before consuming it.
            Textures.glDeleteTextures(b);GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,source);Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,BufferUtils.createIntBuffer(1).put(0,51),GL15.GL_DYNAMIC_DRAW);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,a);Buffers.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,GL30.GL_R32I,source,0,4);draw(p,a,51);
            GL11.glFinish();long second=Context.createWindow(16,16,"Shared resource fixture",0,window);Context.makeCurrent(second);Context.capabilities();write(source,0,61);GL11.glFinish();Context.makeCurrent(window);GL.setCapabilities(caps);draw(p,a,61);Context.destroyWindow(second);
            long independent=Context.createWindow(16,16,"Independent resource fixture",0,0);Context.makeCurrent(independent);Context.capabilities();int other=buffer(71);GL15.glBindBuffer(GL40.GL_DRAW_INDIRECT_BUFFER,other);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,4).getInt(0)==71,"independent ownership");Context.makeCurrent(window);GL.setCapabilities(caps);draw(p,a,61);Context.destroyWindow(independent);
            mirrorAndGpu();
            if(args.length>0&&args[0].equals("--bench"))bench(p,a);
            System.out.println("RESOURCE MUTATION PASS unchanged/partial/copy/map/flush/realloc/delete/name-reuse/format/multiple-consumers/journal/shared-context/GPU-writes/mirror-budget");
        }finally{Context.makeCurrent(window);GL.setCapabilities(caps);Shaders.glDeleteProgram(p);Textures.glDeleteTextures(a);Buffers.glDeleteBuffers(source);Context.destroyWindow(window);GLFW.glfwTerminate();cb.free();}
    }
    static void mirrorAndGpu(){
        int command=buffer(3,1,0,0);GL15.glBindBuffer(GL40.GL_DRAW_INDIRECT_BUFFER,command);long hits=n(MIRROR_HITS);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,16).getInt(0)==3,"owned command");if(Options.MIRROR&&Counters.ENABLED)check(n(MIRROR_HITS)==hits+1,"owned mirror used");write(command,0,6);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,16).getInt(0)==6,"subdata mirror patched");
        int integer=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(integer,1,GL30.GL_RGBA32UI,1,1);int fbo=Gl41.glCreateFramebuffers();GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,fbo);Gl41.glFramebufferTexture2D(GL30.GL_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL11.GL_TEXTURE_2D,integer,0);Gl41.glClearBufferuiv(GL11.GL_COLOR,0,new int[]{3,1,0,0});GL15.glBindBuffer(GL21.GL_PIXEL_PACK_BUFFER,command);GpuWrites.glReadPixels(0,0,1,1,GL30.GL_RGBA_INTEGER,GL11.GL_UNSIGNED_INT,0L);GL15.glBindBuffer(GL21.GL_PIXEL_PACK_BUFFER,0);GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,0);
        hits=n(MIRROR_HITS);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,16).getInt(0)==3,"PBO-produced command read");check(n(MIRROR_HITS)==hits,"PBO must invalidate CPU mirror");
        int tf=Shaders.glCreateProgram(),vs=Shaders.compileRaw(GL20.GL_VERTEX_SHADER,"#version 410 core\nflat out uvec4 args;void main(){args=uvec4(9,1,0,0);gl_Position=vec4(0,0,0,1);}");Shaders.glAttachShader(tf,vs);GL30.glTransformFeedbackVaryings(tf,new CharSequence[]{"args"},GL30.GL_INTERLEAVED_ATTRIBS);Shaders.glLinkProgram(tf);check(GL20.glGetProgrami(tf,GL20.GL_LINK_STATUS)!=0,"TF link");GL20.glDeleteShader(vs);Shaders.glUseProgram(tf);Buffers.glBindBufferBase(GL30.GL_TRANSFORM_FEEDBACK_BUFFER,0,command);GL11.glEnable(GL30.GL_RASTERIZER_DISCARD);Buffers.glBeginTransformFeedback(GL11.GL_POINTS);Draws.glDrawArrays(GL11.GL_POINTS,0,1);Buffers.glEndTransformFeedback();GL11.glDisable(GL30.GL_RASTERIZER_DISCARD);Buffers.glBindBufferBase(GL30.GL_TRANSFORM_FEEDBACK_BUFFER,0,0);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,16).getInt(0)==9,"TF-produced command read");Shaders.glDeleteProgram(tf);int gpuTexture=range(command,0,4),gpuShader=program("i");long gpuCopies=n(RANGE_GL_UPDATES);draw(gpuShader,gpuTexture,9);if(Counters.ENABLED)check(n(RANGE_GL_UPDATES)>gpuCopies,"GPU-produced range keeps GL-copy fallback");Textures.glDeleteTextures(gpuTexture);Shaders.glDeleteProgram(gpuShader);
        GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,command);FloatBuffer typed=BufferUtils.createFloatBuffer(4).put(new float[]{2,3,4,5}).flip();Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,typed,GL15.GL_DYNAMIC_DRAW);check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,16).getFloat(0)==2,"typed native bytes");check(typed.position()==0,"upload does not change position");
        List<Integer> large=new ArrayList<>();for(int i=0;i<18;i++){int id=Buffers.glGenBuffers();large.add(id);GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,id);ByteBuffer bytes=BufferUtils.createByteBuffer(1024*1024);bytes.putInt(0,i);Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,bytes,GL15.GL_DYNAMIC_DRAW);}check(Buffers.mirrorBytesForTest()<=16*1024*1024,"mirror bounded");GL15.glBindBuffer(GL40.GL_DRAW_INDIRECT_BUFFER,large.getFirst());check(Buffers.commands(GL40.GL_DRAW_INDIRECT_BUFFER,0,4).getInt(0)==0,"evicted command falls back correctly");for(int id:large)Buffers.glDeleteBuffers(id);Buffers.glDeleteBuffers(command);Textures.glDeleteTextures(integer);Gl41.glDeleteFramebuffers(fbo);check(GL11.glGetError()==0,"GPU mutations");
    }
    static void bench(int p,int tex)throws Exception{
        Shaders.glUseProgram(p);Samplers.glActiveTexture(GL13.GL_TEXTURE0+80);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,tex);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"pixels"),80);
        int batch=buffer(3,1,0,0,3,1,0,0,3,1,0,0,3,1,0,0);GL15.glBindBuffer(GL40.GL_DRAW_INDIRECT_BUFFER,batch);
        Telemetry.start();double[] passes=new double[13];Telemetry.frame(System.nanoTime(),System.currentTimeMillis(),0);
        for(int block=0;block<30;block++){for(int i=0;i<100;i++)Draws.glMultiDrawArraysIndirect(GL11.GL_TRIANGLES,0,4,0);Telemetry.world(passes,400,400);Telemetry.frame(System.nanoTime(),System.currentTimeMillis(),0);}GL11.glFinish();
        int blocks=Integer.getInteger("vmcompat.benchBlocks",200);long[] totals=new long[Counters.Key.values().length];long start=System.nanoTime();
        for(int block=0;block<blocks;block++){for(int i=0;i<100;i++)Draws.glMultiDrawArraysIndirect(GL11.GL_TRIANGLES,0,4,0);long[] counts=Counters.snapshot();for(int i=0;i<counts.length;i++)if(i==COMMAND_CACHE_PEAK_BYTES.ordinal())totals[i]=Math.max(totals[i],counts[i]);else if(i==COMMAND_CACHE_BYTES.ordinal())totals[i]=counts[i];else totals[i]+=counts[i];Telemetry.world(passes,400,400);Telemetry.frame(System.nanoTime(),System.currentTimeMillis(),0);}
        GL11.glFinish();double elapsed=(System.nanoTime()-start)/1e6;Telemetry.stopForTest();GL15.glBindBuffer(GL40.GL_DRAW_INDIRECT_BUFFER,0);Buffers.glDeleteBuffers(batch);
        Path out=Path.of(System.getProperty("vmcompat.result"));StringBuilder counters=new StringBuilder();for(Counters.Key key:Counters.Key.values()){if(!counters.isEmpty())counters.append(',');counters.append('"').append(key.name()).append("\":").append(totals[key.ordinal()]);}
        Files.writeString(out,"{\"completed_100_batch_block_ms\":"+(elapsed/blocks)+",\"blocks\":"+blocks+",\"draws_per_block\":400,\"telemetry\":\""+Options.TELEMETRY+"\",\"dropped_rows\":"+Telemetry.snapshot(System.nanoTime()).dropped()+",\"counters\":{"+counters+"},\"game_launched\":false}\n");
    }
}
